import { AppShell, Card } from "march/ui"

// gece okuma uygulaması: koyu temada kenar çubuğu ve kayan sayfa
export function NightReader() {
  return <Card m:theme="night">
    <AppShell features={[]} nav={<div sx={{ flex: "col", gap: 1, p: 2 }}><strong>Kitaplık</strong><span>Okunanlar</span><span>Notlar</span></div>}>
      <article sx={{ p: 3 }}><h3 sx={{ text: ["lg", "bold"] }}>Birinci bölüm</h3><p sx={{ text: "sm" }}>Gece yarısı, şehir sustuğunda…</p></article>
    </AppShell>
  </Card>
}

import { AppShell, NavMenu, Button } from "march/ui"
import { home, settings, users } from "march/icons"

// yönetim uygulaması: gezinme menüsü, üstte güncelleme duyurusu (kapatılabilir), seçilen sayfa ana alanda
const pages = [{ id: "home", label: "Özet", icon: home }, { id: "users", label: "Kullanıcılar", icon: users }, { id: "settings", label: "Ayarlar", icon: settings }]

export function AdminApp() {
  let $page = "home"
  let $banner = true
  return <AppShell features={[]} mainId="admin-main"
    top={$banner ? <div class="sc-shell-banner">Yeni sürüm hazır <Button size="sm" on:click={() => $banner = false}>Tamam</Button></div> : null}
    nav={<NavMenu items={pages.map((p) => ({ ...p, onSelect: () => $page = p.id }))} />}>
    <h3 sx={{ p: 3, text: "bold" }}>{pages.find((p) => p.id === $page)!.label}</h3>
  </AppShell>
}

import { AppShell } from "march/ui"

// AppShell, Layout'un çerçeveli (framed) hâli: top, header, nav, aside, footer, mainId, labels, features, class ve içerik
const Box = (props: { children?: unknown }) => <div class="sc-ld-box">{props.children}</div>

export function AppShellLab() {
  return <AppShell class="lab-shell" features={[]} mainId="lab-shell-main" labels={{ skip: "İçeriğe geç" }}
    top={<Box>Duyuru</Box>} header={<Box>Üst bilgi</Box>} nav={<Box>Gezinme</Box>} aside={<Box>Yan alan</Box>} footer={<Box>Alt bilgi</Box>}>
    <Box>Sayfa</Box>
  </AppShell>
}

import { test, expect, renderTest } from "march/testing"
import { AppShellLab } from "./AppShellLab.tsx"

// AppShellLab'in testleri: kaydedince Testler sekmesinde çalışır
test("bölgeler ve içerik çizilir", () => {
  const s = renderTest(() => <AppShellLab />)
  for (const t of ["Duyuru", "Üst bilgi", "Gezinme", "Yan alan", "Alt bilgi", "Sayfa"]) expect(s.sees(t)).toBe(true)
})

test("İçeriğe geç bağlantısı ana alana gider", () => {
  const s = renderTest(() => <AppShellLab />)
  expect(s.get("#lab-shell-main")).not.toBe(null)
  expect(s.get("a[href='#lab-shell-main']")).not.toBe(null)
})
